# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜNYA\'DAKİ SU VARLIĞININ DAĞILIŞI VE DENİZ TÜRLERİ</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">YERYÜZÜNDEKİ SULARIN ORANI</text>\n  <rect x="38" y="82" width="284" height="32" rx="6" fill="#1d4ed8"/>\n  <text x="180" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">Tuzlu Sular (Okyanus ve Denizler): %97</text>\n  <rect x="38" y="122" width="284" height="82" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="140" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0369a1">Tatlı Sular (%3) Kendi İçinde Dağılımı:</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10" fill="#334155">• Buzullar ve Kalıcı Karlar: %68,7</text>\n  <text x="180" y="175" text-anchor="middle" font-size="10" fill="#334155">• Yer Altı Suları: %30,1</text>\n  <text x="180" y="192" text-anchor="middle" font-size="10" font-weight="bold" fill="#0284c7">• Tatlı Yüzey Suları (Göl, Akarsu): %1,2</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">OKYANUSLAR VE DENİZ SINIFLANDIRMASI</text>\n  <rect x="375" y="80" width="290" height="40" rx="6" fill="#ffffff" stroke="#0ea5e9" stroke-width="1.2"/>\n  <text x="520" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#0369a1">Büyüklüğe Göre Okyanuslar:</text>\n  <text x="520" y="112" text-anchor="middle" font-size="9.5" fill="#334155">1. Büyük (Pasifik) &gt; 2. Atlas (Atlantik) &gt; 3. Hint Okyanusu</text>\n  <rect x="375" y="126" width="290" height="40" rx="6" fill="#ffffff" stroke="#0ea5e9" stroke-width="1.2"/>\n  <text x="520" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#0369a1">Kenar Denizler (Kıta Kenarı):</text>\n  <text x="520" y="158" text-anchor="middle" font-size="9.5" fill="#334155">Manş Denizi, Kuzey Denizi, Japon Denizi, Umman Denizi</text>\n  <rect x="375" y="172" width="290" height="40" rx="6" fill="#ffffff" stroke="#0ea5e9" stroke-width="1.2"/>\n  <text x="520" y="188" text-anchor="middle" font-size="10" font-weight="bold" fill="#0369a1">İç Denizler (Boğazlarla Bağlı):</text>\n  <text x="520" y="204" text-anchor="middle" font-size="9.5" fill="#334155">Akdeniz, Karadeniz, Marmara, Kızıldeniz, Baltık Denizi</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">OLUŞUMLARINA GÖRE DOĞAL GÖL TÜRLERİ VE ÖRNEKLERİ</text>\n  <rect x="20" y="45" width="320" height="185" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">A) YERLİ KAYA (ÇANAK) GÖLLERİ</text>\n  <rect x="35" y="78" width="290" height="138" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="180" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">1. Tektonik Göller (Fay ve Çöküntü):</text>\n  <text x="180" y="111" text-anchor="middle" font-size="9.5" fill="#334155">Baykal, Hazar, Lut | Tuz, Beyşehir, Eğirdir, İznik, Sapanca</text>\n  <text x="180" y="131" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">2. Karstik Göller (Polye ve Obruk):</text>\n  <text x="180" y="146" text-anchor="middle" font-size="9.5" fill="#334155">İşkodra | Salda, Kestel, Avlan, Kızören Obruğu</text>\n  <text x="180" y="166" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">3. Volkanik Göller (Krater, Kaldera, Maar):</text>\n  <text x="180" y="181" text-anchor="middle" font-size="9.5" fill="#334155">Nemrut Kalderası, Meke Tuzlası (Maar), Acıgöl, Gölcük</text>\n  <text x="180" y="201" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">4. Buzul (Sirk) Gölleri: Kaçkar, Cilo, Uludağ (Aynalı)</text>\n\n  <rect x="360" y="45" width="320" height="185" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">B) DOĞAL SET GÖLLERİ</text>\n  <rect x="375" y="78" width="290" height="138" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">1. Heyelan Set Gölleri (Karadeniz):</text>\n  <text x="520" y="111" text-anchor="middle" font-size="9.5" fill="#334155">Tortum, Sera, Abant, Yedigöller, Borabay, Zinav</text>\n  <text x="520" y="131" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">2. Alüvyal Set Gölleri (Akarsu Biriktirmesi):</text>\n  <text x="520" y="146" text-anchor="middle" font-size="9.5" fill="#334155">Mogan, Eymir, Bafa (Çamiçi), Köyceğiz, Uzun Göl</text>\n  <text x="520" y="166" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">3. Volkanik (Lav) Set Gölleri (Doğu Anadolu):</text>\n  <text x="520" y="181" text-anchor="middle" font-size="9.5" fill="#334155">Van (Karma), Erçek, Nazik, Çıldır, Haçlı, Balık</text>\n  <text x="520" y="201" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">4. Kıyı Set (Lagün): Büyükçekmece, Küçükçekmece, Durusu</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YER ALTI SU KAYNAKLARI VE ÖZELLİKLERİ</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">SOĞUK SU KAYNAKLARI</text>\n  <rect x="35" y="78" width="290" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="180" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">1. Yamaç (Vadi / Tabaka) Kaynağı:</text>\n  <text x="180" y="110" text-anchor="middle" font-size="9.5" fill="#334155">Vadi yamaçlarının yer altı su tablasını kesmesiyle oluşur.</text>\n  <rect x="35" y="124" width="290" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="180" y="140" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">2. Karstik Kaynak (Voklüz):</text>\n  <text x="180" y="156" text-anchor="middle" font-size="9.5" fill="#334155">Kalkerli arazilerde çıkar; suları soğuk, kireçli ve gürdür.</text>\n  <rect x="35" y="170" width="290" height="40" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="180" y="186" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">3. Artezyen Kaynağı (Sondaj):</text>\n  <text x="180" y="202" text-anchor="middle" font-size="9.5" fill="#334155">İki geçirimsiz tabaka arasındaki basınçlı suyun sondajla çıkışı.</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">SICAK (JEOTERMAL) SU KAYNAKLARI</text>\n  <rect x="375" y="78" width="290" height="62" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.2"/>\n  <text x="520" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">4. Fay Kaynağı (Kaplıca / Ilıca):</text>\n  <text x="520" y="112" text-anchor="middle" font-size="9.5" fill="#334155">Fay hatları boyunca çıkar; debisi yıl boyu değişmez,</text>\n  <text x="520" y="128" text-anchor="middle" font-size="9.5" fill="#334155">çözünmüş mineral oranı yüksektir (Türkiye\'de çok yaygındır).</text>\n  <rect x="375" y="148" width="290" height="62" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.2"/>\n  <text x="520" y="166" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">5. Gayzer Kaynağı (Volkanik Fışkırma):</text>\n  <text x="520" y="182" text-anchor="middle" font-size="9.5" fill="#334155">Aktif volkanik sahalarda (İzlanda, ABD, Yeni Zelanda)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="9.5" fill="#334155">sıcak su ve buharın periyodik olarak fışkırmasıyla oluşur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
